import {PixelSimulation,GEAR_CATALOG,FISHING_SPOTS,HARBOR} from './pixel-sim.js?v=20260927-pixel-v2';
import {createPixelSprites} from './pixel-sprites.js?v=20260927-pixel-v2';
import {createPixelWorld} from './pixel-world.js?v=20260927-pixel-v2';
import {bindPointer,stickVector,ActionSources} from './input.js?v=20260927-pixel-v2';
import {OceanAudio} from './audio.js?v=20260927-pixel-v2';
import {sea,marineSummary,updateSea} from './marine.js?v=20260927-pixel-v2';
import {depthInfoAt} from './bathymetry.js?v=20260927-pixel-v2';
