const $=id=>document.getElementById(id),show=(id,value)=>{$(id).hidden=!value;},txt=(id,v)=>{if($(id).textContent!==String(v))$(id).textContent=v;};
const SAVE='santa-cruz-pixel-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE)||'null');}catch{}
const sim=new PixelSimulation({saved,conditions:sea}),sprites=createPixelSprites(),world=createPixelWorld($('world'),{sprites}),audio=new OceanAudio();
const keys=new Set(),sources=new ActionSources(),pointers=[];let stick={x:0,y:0},stickDriving=false,menu=null,lastFocus=null,toastTimer=null,lastToastId=0,lastFishState='idle',lastFrame=performance.now(),uiElapsed=0,saveElapsed=0,frames=0,fps=60,fpsTimer=0,reelToggle=false,started=false,castOwner=null;
function drawAsset(canvas,asset){if(!asset)return;canvas.width=asset.width;canvas.height=asset.height;canvas.getContext('2d').drawImage(asset,0,0);}
for(const el of document.querySelectorAll('[data-icon]'))drawAsset(el,sprites.icons[el.dataset.icon]);
show('resume-btn',Boolean(saved?.edition==='pixel'));world.resize(innerWidth,innerHeight);
function toast(message){if(!message)return;txt('toast',message);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function feedback(result){if(result?.message)toast(result.message);if(result?.action==='staff')openStaff();updateUI();return result;}
function persist(){if(sim.state.mode==='intro')return;try{localStorage.setItem(SAVE,JSON.stringify(sim.snapshot()));}catch{}}
function clearInputs(){keys.clear();sources.clear();stick={x:0,y:0};if(stickDriving&&sim.state.engine)sim.setThrottle(0);stickDriving=false;reelToggle=false;for(const p of pointers)p.reset();$('stick-thumb').style.transform='';sim.cancelCast();castOwner=null;}
function start(resume=false){closeModal();feedback(sim.start(resume));started=true;audio.init();$('app').classList.remove('is-intro');show('intro',false);show('intro-location',false);for(const id of['trip-tools','trip-info','controls'])show(id,true);lastFrame=performance.now();persist();updateUI();}
function openModal(kind,html){lastFocus=document.activeElement;clearInputs();menu=kind;sim.pause(true);$('modal-content').innerHTML=html;show('modal-layer',true);$('modal').scrollTop=0;$('close-modal').focus();updateUI();}
function closeModal(){if(!menu)return;menu=null;show('modal-layer',false);clearInputs();sim.pause(document.hidden);lastFocus?.focus?.();updateUI();}
const heading=(eyebrow,title,description='')=>`<div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2>${description?`<p class="modal-desc">${description}</p>`:''}`;
const button=(id,label,primary=false)=>`<button id="${id}" class="${primary?'primary':'secondary'}">${label}</button>`;
function openStaff(){const s=sim.state;if(!sim.atCounter){feedback(sim.walkTo('counter'));return;}openModal('staff',heading('SANTA CRUZ BOAT RENTALS','码头小屋')+`<div class="staff-banner"><canvas id="staff-portrait"></canvas><p><b>值班员 · 码头小屋</b>早上好！装备在柜子里。<br>船放稳以后，沿左侧台阶下去。</p></div><div class="button-row">${button('pack-starter','带上基础装备',true)}${button('staff-bag','整理背包')}${button('staff-shop','兑换装备')}</div><div class="button-row">${button('staff-trade','兑换鱼获')}${button('staff-restock','免费补给')}</div><div class="button-row">${button('launch-boat',s.launchStage==='stored'?'请工作人员吊艇':'走向登船平台',true)}</div><p class="credits-note">鱼获兑换为游戏内潮汐点。保留与放流都能记录收获。</p>`);drawAsset($('staff-portrait'),sprites.dockWorker);$('pack-starter').onclick=()=>{feedback(sim.packStarter());persist();};$('staff-bag').onclick=()=>openGear();$('staff-shop').onclick=()=>openGear('shop');$('staff-trade').onclick=()=>{feedback(sim.trade());persist();};$('staff-restock').onclick=()=>feedback(sim.restock());$('launch-boat').onclick=()=>{closeModal();feedback(sim.launchBoat());feedback(sim.walkTo('boarding'));};}
function openGear(tab='pack',filter='all'){
 const s=sim.state,owned=s.profile.owned,categories={all:'全部',fishing:'竿线钓组',bait:'鱼饵',other:'船上用品'};const catalog=GEAR_CATALOG.filter(g=>tab==='shop'?g.price>0:owned.includes(g.id)).filter(g=>filter==='all'||(filter==='fishing'?['rod','reel','line','leader','rig','weight'].includes(g.slot):filter==='bait'?['bait','consumable'].includes(g.slot):!['rod','reel','line','leader','rig','weight','bait','consumable'].includes(g.slot)));
 openModal('gear',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('YOUR TACKLE BOX',tab==='shop'?'装备兑换':'随身装备',`${s.packed.length} 件已携带 · 装备 ${sim.stats.weight.toFixed(1)} kg · 冰箱 ${sim.stats.capacity} kg`)+`<div class="tabs"><button data-tab="pack" class="${tab==='pack'?'active':''}">背包</button><button data-tab="rig" class="${tab==='rig'?'active':''}">钓组</button><button data-tab="shop" class="${tab==='shop'?'active':''}">装备商店</button></div>`+(tab==='rig'?rigHTML():`<div class="tabs">${Object.entries(categories).map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div><div class="gear-grid">${catalog.map(g=>{const packed=s.packed.includes(g.id),isOwned=owned.includes(g.id)&&g.slot!=='consumable';return`<article class="gear-card"><strong>${esc(g.name)}</strong><p>${esc(g.desc)}</p><small>${tab==='shop'?`✦ ${g.price}`:`${g.kg} kg`}</small><button data-item="${g.id}" class="${packed?'equipped':''}" ${tab==='shop'&&isOwned?'disabled':''}>${tab==='shop'?(isOwned?'已拥有':'兑换'):packed?'✓ 已带上':'带上'}</button></article>`;}).join('')}</div>${!sim.atCounter?'<p class="credits-note">返回码头小屋，可以购买与装卸装备。海上可随时更换已经带上的钓组。</p>':''}`));
 for(const el of document.querySelectorAll('[data-tab]'))el.onclick=()=>openGear(el.dataset.tab);for(const el of document.querySelectorAll('[data-filter]'))el.onclick=()=>openGear(tab,el.dataset.filter);for(const el of document.querySelectorAll('[data-item]'))el.onclick=()=>{const r=tab==='shop'?sim.buyGear(el.dataset.item):sim.equip(el.dataset.item);feedback(r);persist();if(r.ok)openGear(tab,filter);};
 if(tab==='rig'){$('apply-rig').onclick=()=>{const r=sim.setRig({rig:$('rig-select').value,bait:$('bait-select').value,rod:$('rod-select').value,drag:Number($('rig-drag').value)});feedback(r);if(r.ok)closeModal();};$('rig-drag').oninput=()=>txt('rig-drag-label',`${Math.round(Number($('rig-drag').value)*100)}%`);}
}
function rigHTML(){const s=sim.state,option=(value,label,selected,disabled=false)=>`<option value="${value}" ${selected===value?'selected':''} ${disabled?'disabled':''}>${label}</option>`;return `<div class="form-row"><label for="rod-select">船竿</label><select id="rod-select">${GEAR_CATALOG.filter(g=>g.slot==='rod'&&s.packed.includes(g.id)).map(g=>option(g.id,g.name,s.profile.loadout.rod)).join('')}</select></div><div class="form-row"><label for="rig-select">钓组</label><select id="rig-select">${[['bottom','沉底钓组','tackle'],['slider','滑铅钓组','rig_slider'],['jig','铅头软饵','rig_jig'],['float','浮游钓组','rig_float']].map(([id,label,item])=>option(id,label,s.rig,!s.packed.includes(item))).join('')}</select></div><div class="form-row"><label for="bait-select">鱼饵</label><select id="bait-select">${[['squid','鱿鱼条'],['anchovy','鳀鱼'],['shrimp','虾饵'],['sardine','沙丁鱼'],['jig','软饵']].map(([id,label])=>option(id,`${label} · ${s.profile.stock[id]||0} 份`,s.bait)).join('')}</select></div><div class="form-row"><label for="rig-drag">泄力 <b id="rig-drag-label">${Math.round(s.drag*100)}%</b></label><input id="rig-drag" type="range" min=".2" max=".85" step=".01" value="${s.drag}"></div><div class="button-row">${button('apply-rig','装好钓组',true)}</div><p class="credits-note">不同水深、底质、钓组与鱼饵影响遇鱼概率。没有鱼种解锁门槛。</p>`;}
function openMap(){const s=sim.state,p=s.mode==='walk'?{x:s.playerX,z:s.playerZ}:{x:s.boatX,z:s.boatZ};openModal('map',heading('MONTEREY BAY','海上去处','选一个地方，按真实船速慢慢过去。也可以用摇杆自由驾驶。')+`<canvas id="chart" class="map-canvas" width="540" height="240" aria-label="Santa Cruz 海岸与钓点"></canvas><div class="spot-list">${FISHING_SPOTS.map((spot,i)=>`<button class="spot-button" data-spot="${i}"><div><strong>${i+1}. ${spot.name}</strong><small>${{sand:'沙底 · 混合近岸鱼',kelp:'海带 · 岩鱼',reef:'岩礁 · 混合鱼群'}[spot.kind]}</small></div><span>${(Math.hypot(spot.x-p.x,spot.z-p.z)/1000).toFixed(2)} km →</span></button>`).join('')}<button id="return-dock" class="spot-button"><div><strong>↩ 返回码头小屋</strong><small>靠泊、兑换鱼获、补充装备</small></div><span>${Math.round(Math.hypot(p.x-HARBOR.returnX,p.z-HARBOR.returnZ))} m</span></button></div><p class="credits-note">海岸轮廓：OpenStreetMap contributors · 地形参考：NOAA。像素建筑与人物为艺术化绘制。</p>`);drawChart();for(const el of document.querySelectorAll('[data-spot]'))el.onclick=()=>{const target=FISHING_SPOTS[Number(el.dataset.spot)];closeModal();feedback(sim.selectWaypoint(target));};$('return-dock').onclick=()=>{closeModal();feedback(sim.state.mode==='walk'?sim.walkTo('counter'):sim.selectWaypoint('dock'));};}
function drawChart(){const c=$('chart'),ctx=c.getContext('2d'),W=c.width,H=c.height;const bounds={minX:-2400,maxX:3900,minZ:-2200,maxZ:900},sx=W/(bounds.maxX-bounds.minX),sz=H/(bounds.maxZ-bounds.minZ),pt=(x,z)=>[(x-bounds.minX)*sx,(z-bounds.minZ)*sz];ctx.fillStyle='#32858a';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#9bd0bd22';ctx.lineWidth=1;for(let x=0;x<W;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}for(const rings of[landPolygons,pierRings])for(const ring of rings){ctx.beginPath();ring.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](...pt(p.x,p.z)));ctx.closePath();ctx.fillStyle=rings===pierRings?'#bc8867':'#d2ce9d';ctx.fill();}ctx.font='10px monospace';for(const [i,p]of FISHING_SPOTS.entries()){const[x,y]=pt(p.x,p.z);ctx.fillStyle='#fff1d5';ctx.fillRect(x-4,y-4,8,8);ctx.fillText(String(i+1),x+9,y+4);}const s=sim.state,[x,y]=pt(s.boatX,s.boatZ);ctx.fillStyle='#f08d6d';ctx.fillRect(x-4,y-4,8,8);ctx.fillStyle='#fff1d5';ctx.fillText('YOU',x+9,y-3);ctx.fillText('SANTA CRUZ',20,23);ctx.fillStyle='#a6d4c4';ctx.fillText('MONTEREY BAY',W-115,H-17);}
function fishSprite(f){return sprites.fish[f?.name?.includes('比目')?'halibut':f?.name?.includes('鲭')?'mackerel':f?.name?.includes('单线')?'lingcod':'rockfish'];}
function openCatch(){const f=sim.state.fish;if(!f)return;openModal('catch',heading('A MOMENT TO REMEMBER',esc(f.name),esc(f.latin))+`<div class="catch-hero"><canvas id="catch-art"></canvas></div><div class="catch-stats"><div><strong>${f.length}</strong><small>厘米</small></div><div><strong>${f.kg}</strong><small>千克</small></div><div><strong>${Math.round(sim.state.fightTime)}</strong><small>搏鱼秒数</small></div></div><div class="button-row">${button('keep-fish','收入冰箱',true)}${button('release-fish','记录并放流')}</div>`);drawAsset($('catch-art'),fishSprite(f));$('keep-fish').onclick=()=>{const r=sim.keepCatch();feedback(r);if(r.ok){closeModal();persist();}};$('release-fish').onclick=()=>{feedback(sim.releaseCatch());closeModal();persist();};}
function openJournal(){const s=sim.state;openModal('journal',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('THE DAYS WE KEEP','鱼获与航程',`航行 ${(s.sailed/1000).toFixed(2)} km · 抛竿 ${s.casts} 次 · 鱼获 ${s.catches.length} 条`)+(s.catches.length?s.catches.slice().reverse().map((f,i)=>`<div class="catch-row"><canvas id="journal-fish-${i}"></canvas><div><b>${esc(f.name)}</b><small>${f.length} cm · ${f.kg} kg · ${f.time}</small></div><span>${f.settled?'已记录':f.kept?'冰箱中':'已放流'}</span></div>`).join(''):'<p class="journal-empty">冰箱里还很安静。<br>好故事，总会从第一竿开始。</p>')+`<h3>航海手记</h3><div class="key-list">${s.journal.slice(0,10).map(j=>`${j.time}　${esc(j.text)}`).join('<br>')}</div>`);s.catches.slice().reverse().forEach((f,i)=>drawAsset($(`journal-fish-${i}`),fishSprite(f)));}
function openSettings(){const m=marineSummary();openModal('settings',heading('SLOW DOWN, CAST OUT','海风与设置')+`<div class="settings-grid">${button('settings-audio',`环境声音：${audio.enabled?'开':'关'}`)}${button('settings-photo','保存像素风景')}${started?button('settings-rescue','呼叫免费救援'):''}</div><h3>操作</h3><p class="key-list">移动：左下摇杆 / WASD<br>操船：上下前进、倒车，左右转向，松手回空挡<br>抛竿：按住抛竿 / 空格，松开抛出<br>咬钩：点提竿 / 空格；搏鱼：按住收线 / F<br>E 互动 · Q 锚 · R 引擎 · I 装备 · M 海图<br>点击码头地面可步行；点击水面可设置航向。</p><h3>今天的海</h3><p class="credits-note">${m.label} · 风 ${sea.windKnots.toFixed(1)} kn · 浪 ${sea.waveHeight.toFixed(1)} m · 海温 ${sea.waterTemp.toFixed(1)} °C<br>观测时间：${m.observedAt?new Date(m.observedAt).toLocaleString('zh-CN',{timeZone:'America/Los_Angeles'}):'暂不可用'}（Santa Cruz）<br>区域浮标距离约 23–40 km，非船边实测。<br>每次出发从 06:00 开始，航程时间 1:1；打开菜单时暂停。</p><p class="credits-note">原创 Canvas 像素美术 · 海岸数据 <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a> · <a href="https://www.ndbc.noaa.gov/station_page.php?station=46236" target="_blank" rel="noopener">NOAA 海况</a>。人物为虚构值班员。鱼获交易使用游戏积分。</p>`);$('settings-audio').onclick=()=>{audio.init();audio.toggle();openSettings();};$('settings-photo').onclick=()=>{closeModal();const a=document.createElement('a');a.href=$('world').toDataURL('image/png');a.download='santa-cruz-pixel.png';a.click();};if($('settings-rescue'))$('settings-rescue').onclick=()=>{closeModal();feedback(sim.rescue());persist();};}
function openActions(){const s=sim.state;openModal('actions',heading('ABOARD YOUR SKIFF','船上时光')+`<div class="settings-grid">${button('action-stand',s.standing?'坐回驾驶座':'站起来活动')}${button('action-jump','从船边入水')}${button('action-rig','整理钓组')}${s.packed.includes('sounder')?button('action-sounder','查看测深仪'):''}${button('action-return','返航')}${button('action-retrieve','收回钓组')}</div>`);$('action-stand').onclick=()=>{closeModal();feedback(sim.stand());};$('action-jump').onclick=()=>{closeModal();audio.splash();feedback(sim.jump());};$('action-rig').onclick=()=>openGear('rig');if($('action-sounder'))$('action-sounder').onclick=openSounder;$('action-return').onclick=()=>{closeModal();feedback(sim.selectWaypoint('dock'));};$('action-retrieve').onclick=()=>{closeModal();feedback(sim.retrieve());};}
function openSounder(){const s=sim.state;openModal('sounder',heading('BOTTOM PROFILE','船下的起伏','沿船首方向前后各 50 m · NOAA 地形参考')+`<canvas id="sounder-chart" class="map-canvas" width="540" height="240"></canvas><p class="credits-note">历史 MHW 地形网格约 20.7 m 分辨率；不显示或保证鱼群。</p>`);const c=$('sounder-chart'),x=c.getContext('2d'),samples=Array.from({length:81},(_,i)=>{const d=(i-40)*1.25;return depthInfoAt(s.boatX-Math.sin(s.heading)*d,s.boatZ-Math.cos(s.heading)*d).value??0;}),max=Math.max(12,...samples)*1.2;x.fillStyle='#245f70';x.fillRect(0,0,540,240);x.strokeStyle='#72bca8';x.lineWidth=2;x.beginPath();samples.forEach((d,i)=>{const px=20+i*6.25,py=30+d/max*180;x[i?'lineTo':'moveTo'](px,py);});x.lineTo(520,220);x.lineTo(20,220);x.closePath();x.fillStyle='#a2a47b';x.fill();x.stroke();x.fillStyle='#fff1d5';x.font='12px monospace';x.fillText('-50 m',20,17);x.fillText('BOAT',253,17);x.fillText('+50 m',475,17);x.fillText(`${samples[40].toFixed(1)} m`,279,40);x.setLineDash([3,3]);x.strokeStyle='#fff1d5';x.beginPath();x.moveTo(270,25);x.lineTo(270,217);x.stroke();}
$('start-btn').onclick=()=>start();$('resume-btn').onclick=()=>start(true);$('close-modal').onclick=closeModal;$('audio-btn').onclick=()=>{audio.init();audio.toggle();txt('audio-btn',audio.enabled?'♪':'♩');};$('settings-btn').onclick=openSettings;$('gear-btn').onclick=()=>openGear();$('map-btn').onclick=openMap;$('journal-btn').onclick=openJournal;$('credits-btn').onclick=openJournal;$('more-btn').onclick=openActions;$('engine-btn').onclick=()=>feedback(sim.toggleEngine());$('anchor-btn').onclick=()=>feedback(sim.toggleAnchor());$('interact-btn').onclick=()=>feedback(sim.interact());$('drag-minus').onclick=()=>{sim.changeDrag(-.05);updateUI();};$('drag-plus').onclick=()=>{sim.changeDrag(.05);updateUI();};
$('guide-btn').onclick=()=>{const s=sim.state;if(s.mode==='walk'){if(sim.atCounter&&s.launchStage==='stored'){openStaff();return;}feedback(sim.walkTo(s.launchStage==='stored'||s.tripComplete?'counter':'boarding'));}else if(s.mode==='swim')feedback(sim.stand());else openMap();};
function castDown(source){if(menu)return false;const s=sim.state;if(s.fishState==='landed'){openCatch();return false;}if(s.fishState==='fight'){sources.set('pump',source,true);return true;}const r=sim.startCast();feedback(r);if(r.action==='casting'){castOwner=source;audio.cast();}return r.ok;}
function castUp(source,cancel=false){sources.set('pump',source,false);if(sim.state.casting&&castOwner===source){castOwner=null;feedback(cancel?sim.cancelCast():sim.releaseCast());}}
function stickMove(e){const r=$('joystick').getBoundingClientRect();stick=stickVector(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2,r.width*.4);$('stick-thumb').style.transform=`translate(${stick.x*r.width*.3}px,${stick.y*r.height*.3}px)`;}
function stickEnd(){stick={x:0,y:0};$('stick-thumb').style.transform='';if(stickDriving&&sim.state.engine)sim.setThrottle(0);stickDriving=false;}
pointers.push(bindPointer($('joystick'),{start:e=>{if(menu)return false;stickMove(e);},move:stickMove,end:stickEnd,cancel:stickEnd}));
pointers.push(bindPointer($('cast-btn'),{start:()=>castDown('pointer'),end:()=>castUp('pointer'),cancel:()=>castUp('pointer',true)}));
pointers.push(bindPointer($('reel-btn'),{start:()=>{if(menu)return false;sources.set('reel','pointer',true);},end:()=>sources.set('reel','pointer',false),cancel:()=>sources.set('reel','pointer',false)}));
let canvasDown=null;pointers.push(bindPointer($('world'),{start:e=>{canvasDown={x:e.clientX,y:e.clientY};},end:e=>{if(!started||menu||!canvasDown||Math.hypot(e.clientX-canvasDown.x,e.clientY-canvasDown.y)>12)return;const p=world.screenToWorld(e.clientX,e.clientY),s=sim.state;if(s.mode==='walk')feedback(sim.walkTo(p));else if(s.mode==='boat'&&s.fishState==='idle'&&!s.moored)feedback(sim.selectWaypoint(p));}}));
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if(menu){if(e.key==='Tab'){const focusable=[...$('modal').querySelectorAll('button:not(:disabled),select,input,a[href]')].filter(el=>!el.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(!started)return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','f'].includes(k))e.preventDefault();if(e.repeat)return;keys.add(k);if(k===' ')castDown('keyboard');if(k==='f')sources.set('reel','keyboard',true);if(k==='e')feedback(sim.interact());if(k==='q')feedback(sim.toggleAnchor());if(k==='r')feedback(sim.toggleEngine());if(k==='i')openGear();if(k==='m')openMap();if(k==='j')openJournal();if(k==='g')$('guide-btn').click();});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(k===' ')castUp('keyboard');if(k==='f')sources.set('reel','keyboard',false);if(['w','s','arrowup','arrowdown'].includes(k)&&sim.state.mode==='boat'&&sim.state.engine&&!sim.state.waypoint)sim.setThrottle(0);});
window.addEventListener('blur',()=>{clearInputs();sim.pause(true);});window.addEventListener('focus',()=>{sim.pause(document.hidden||Boolean(menu));lastFrame=performance.now();});window.addEventListener('resize',()=>{clearInputs();world.resize(innerWidth,innerHeight);});document.addEventListener('visibilitychange',()=>{clearInputs();sim.pause(document.hidden||Boolean(menu));lastFrame=performance.now();persist();});window.addEventListener('pagehide',persist);
function input(){const x=stick.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),z=stick.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),s=sim.state,result={moveX:x,moveZ:z,steer:-x,reel:reelToggle||sources.sources.get('reel')?.size>0,pump:sources.sources.get('pump')?.size>0};if(s.mode==='boat'&&!s.standing&&(Math.abs(z)>.05||Math.abs(x)>.05)&&s.engine){result.throttle=Math.max(-.3,-z);stickDriving=true;}return result;}
