 txt('guide-btn',s.mode==='walk'?(s.tripComplete?'回小屋兑换 ↗':s.launchStage==='stored'?'去租船小屋 ↗':'去登船平台 ↗'):s.mode==='swim'?'游向船尾梯':'选择钓点 ↗');txt('stick-label',s.mode==='walk'?'行走 · WASD':s.mode==='swim'?'游泳':s.standing?'船上活动':'转向 / 前进倒车');show('engine-btn',sailing&&!s.standing);show('anchor-btn',sailing&&!s.moored);show('more-btn',sailing);txt('engine-btn',s.engine?'关闭引擎':'启动引擎');txt('anchor-btn',s.anchor?'起锚':'下锚');const interaction=sim.interaction();show('interact-btn',Boolean(interaction)&&fish!=='bite');txt('interact-label',interaction);show('cast-btn',sailing&&!s.moored&&!s.engine&&!s.docking);show('reel-btn',fish==='fight');show('drag-control',fish==='fight');txt('drag-label',`泄力 ${Math.round(s.drag*100)}%`);txt('cast-label',fish==='fight'?'提竿':fish==='bite'?'提竿！':fish==='landed'?'查看鱼获':['sinking','waiting','flight'].includes(fish)?'收回':'抛竿');txt('cast-hint',fish==='fight'?'按住抬竿':fish==='bite'?'现在！':['sinking','waiting','flight','landed'].includes(fish)?'轻点':'按住 · 松开抛');
 show('fish-status',fish!=='idle'&&fish!=='landed');show('tension-row',fish==='fight');show('cast-row',s.casting);txt('fish-title',({casting:'手里的这一竿',flight:'鱼饵划过海风',sinking:'鱼饵正在下沉',waiting:'等一尾鱼',bite:'咬钩了！',fight:'与鱼周旋'})[fish]||'');txt('fish-distance',fish==='fight'?`${s.lineDistance.toFixed(1)} m`:'');txt('fish-detail',fish==='fight'?'按住收线，张力过高时松手。':fish==='bite'?'点「提竿」':fish==='waiting'?'留意浮漂的动静。':fish==='sinking'?`钓组深度 ${s.lureDepth.toFixed(1)} m`:'');$('tension-fill').style.width=`${Math.min(100,s.tension)}%`;$('tension-fill').style.background=s.tension>80?'#d7745e':'#3d9b94';$('stamina-fill').style.width=`${s.stamina}%`;$('power-fill').style.width=`${s.castPower*100}%`;txt('tension-value',`${Math.round(s.tension)}%`);txt('stamina-value',`${Math.round(s.stamina)}%`);
 if(s.toastId!==lastToastId){lastToastId=s.toastId;toast(s.toast);}if(fish==='bite'&&lastFishState!=='bite'){audio.ping(830,.15,.055);if(navigator.vibrate)navigator.vibrate([70,60,70]);}const newlyLanded=fish==='landed'&&lastFishState!=='landed';lastFishState=fish;if(newlyLanded)openCatch();
 $('game-state').textContent=JSON.stringify({...sim.publicState(),menu,rendererFPS:Math.round(fps),viewport:{width:innerWidth,height:innerHeight},build:'20260927-pixel-v2'});
